fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> Vec<u8> {
    // Since `offset + count` is guaranteed not to exceed `buffer.len()`,
    // we can safely take a slice and convert it to a Vec<u8>.
    buffer[offset..offset + count].to_vec()
}

